// ---------------------------------------------------------------------------
// Validation report store (Validate button, 2026-07-21). Each on-demand or
// post-fill validation pass writes its structured notes — question, options,
// expected/actual, verdict per field — under its OWN storage key, same
// pattern as the document store: the main zod-parsed store never carries
// transient page state, and no migration is needed for a ledger that can be
// regenerated by pressing Validate again.
//
// The live AI-fill pass reads the IN-MEMORY report (its fieldIds are only
// valid within the page instance that produced them); this copy is the
// durable, inspectable record — and the read path for any future Options UI.
// ---------------------------------------------------------------------------

import type { FieldValidation, ValidationSummary } from '@/content/validate'

export const VALIDATION_KEY = 'flashfiller_validation_v1'
export const VALIDATION_SCHEMA_VERSION = 1

/** A notes ledger, not history — keep only the last few pages' reports. */
export const MAX_STORED_REPORTS = 5

export interface StoredValidationReport {
  /** Page (frame) the report describes — frames each store their own. */
  url: string
  at: number
  summary: ValidationSummary
  entries: FieldValidation[]
}

interface ValidationEnvelope {
  schemaVersion: number
  reports: StoredValidationReport[]
}

function isStoredReport(raw: unknown): raw is StoredValidationReport {
  if (typeof raw !== 'object' || raw === null) return false
  const r = raw as Record<string, unknown>
  return typeof r.url === 'string' && typeof r.at === 'number' && Array.isArray(r.entries)
}

/** Tolerant read: corrupt payloads yield an empty envelope — a report is
 *  always regenerable, never worth a poisoned pipeline. */
async function readEnvelope(): Promise<ValidationEnvelope> {
  const result = await chrome.storage.local.get(VALIDATION_KEY)
  const raw = result[VALIDATION_KEY] as Partial<ValidationEnvelope> | undefined
  const reports = Array.isArray(raw?.reports) ? raw.reports.filter(isStoredReport) : []
  return { schemaVersion: VALIDATION_SCHEMA_VERSION, reports }
}

/** Newest first; a re-validation of the same page replaces its old report
 *  instead of stacking stale duplicates. Read-modify-write without a lock:
 *  frames validating in the same instant can lose each other's write
 *  (last-writer-wins). Accepted — the ledger is a convenience copy, always
 *  regenerable with another Validate press; the live pass reads memory. */
export async function saveValidationReport(report: StoredValidationReport): Promise<void> {
  const env = await readEnvelope()
  env.reports = [report, ...env.reports.filter((r) => r.url !== report.url)].slice(
    0,
    MAX_STORED_REPORTS,
  )
  await chrome.storage.local.set({ [VALIDATION_KEY]: env })
}

export async function loadValidationReports(): Promise<StoredValidationReport[]> {
  return (await readEnvelope()).reports
}

export async function loadValidationReport(url: string): Promise<StoredValidationReport | null> {
  return (await readEnvelope()).reports.find((r) => r.url === url) ?? null
}
